typedef enum _nslSourceTypeEnum
{
  NSL_SOURCETYPE_SFX = 0,
  NSL_SOURCETYPE_AMBIENT,
  NSL_SOURCETYPE_MUSIC,
  NSL_SOURCETYPE_VOICE,
  NSL_SOURCETYPE_MOVIE,
  NSL_SOURCETYPE_USER1,
  NSL_SOURCETYPE_USER2,
  NSL_SOURCETYPE_Z
} nslSourceTypeEnum;

struct nslSystem
{
  char pad0[0x15850];
  int initialized;
  char pad1[0x38];
  float sfxVolume;
  float ambientVolume;
  float musicVolume;
  float voiceVolume;
  float movieVolume;
  float user1Volume;
  float user2Volume;
};

extern nslSystem nsl;
void _nslInitialized();
void nslFatal(const char*, ...);

__asm__(".equ nsl, 0x004AB5F0");
__asm__(".equ _nslInitialized__Fv, 0x003912A0");
__asm__(".equ nslFatal__FPCce, 0x00391420");

void nslSetVolume( nslSourceTypeEnum typeOfSound, float newVolume )
{
  if (!nsl.initialized) return;
  _nslInitialized();
  switch(typeOfSound) 
  {
    case NSL_SOURCETYPE_SFX:      nsl.sfxVolume = newVolume;     break;
    case NSL_SOURCETYPE_MUSIC:    nsl.musicVolume = newVolume;   break;
    case NSL_SOURCETYPE_AMBIENT:  nsl.ambientVolume = newVolume; break;
    case NSL_SOURCETYPE_VOICE:    nsl.voiceVolume = newVolume;   break;
    case NSL_SOURCETYPE_MOVIE:    nsl.movieVolume = newVolume;   break;
    case NSL_SOURCETYPE_USER1:    nsl.user1Volume = newVolume;   break;
    case NSL_SOURCETYPE_USER2:    nsl.user2Volume = newVolume;   break;

    default: nslFatal(false && "Unhandled sourcetype"); break;
  };
}
